h,.table td{text-align:left;padding:13px 10px;border-bottom:1px solid #edf1f8;font-size:13px;vertical-align:middle}.table th{color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:.04em}.table tr:last-child td{border-bottom:0}.btn{border:0;border-radius:9px;padding:10px 13px;font-size:12px;font-weight:800;background:#155eef;color:#fff}.btn.secondary{background:#eaf1ff;color:#155eef}.btn.danger{background:#ffebeb;color:#a92e2e}.btn.ghost{background:#f1f4f9;color:#344563}.actions{display:flex;gap:7px;flex-wrap:wrap}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.field{border:1px solid #d9e3f1;border-radius:10px;padding:11px 12px;background:white;color:#17243c;min-width:0}.toolbar .field{flex:1;min-width:170px}.empty{padding:30px;text-align:center;color:#687994}.item{border:1px solid #e4ebf6;border-radius:13px;padding:15px;margin-bottom:10px}.item h3{margin:0 0 7px;font-size:15px}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.timeline{border-left:2px solid #dce7fa;margin:14px 0 14px 9px;padding-left:18px}.timeline p{margin:0 0 15px;font-size:13px}.photo{background:linear-gradient(135deg,#e9f1ff,#c8daf9);border:1px dashed #8aace8;min-height:150px;border-radius:11px;display:grid;place-items:center;text-align:center;color:#345c9d;font-size:13px;padding:12px}.photos{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:12px 0}.photo img{width:100%;max-height:210px;object-fit:cover;border-radius:8px}.detail{display:grid;gap:12px}.detail label{font-size:12px;font-weight:800;color:#53627a;display:grid;gap:6px}.detail textarea{min-height:85px;resize:vertical}.modalback{position:fixed;inset:0;background:#101f3eb0;display:none;place-items:center;z-index:30;padding:15px}.modalback.open{display:grid}.modal{background:white;border-radius:19px;padding:25px;width:min(680px,100%);max-height:90vh;overflow:auto}.modal h2{margin:0 0 8px}.notice{background:#edf4ff;border-radius:12px;padding:13px;color:#345c9d;font-size:12px}.toast{position:fixed;bottom:20px;right:20px;background:#14294b;color:white;padding:13px 18px;border-radius:11px;display:none;z-index:50;max-width:340px}.mini{font-size:12px}.mobilebar{display:none}@media(max-width:1050px){.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:720px){.shell{display:block}.sidebar{position:static;height:auto;padding:16px}.brand{margin:0}.sub{margin:4px 0 10px}.sidenav{display:flex;overflow-x:auto;gap:5px}.navbtn{white-space:nowrap;width:auto;margin:0;padding:10px}.main{padding:20px 13px 50px}.stats{gap:9px}.card{padding:15px}.stat strong{font-size:24px}.photos{grid-template-columns:1fr}}
</style><meta name="api-base" content="{{ url('/api/v1') }}"><meta name="login-url" content="{{ url('/login') }}"><meta name="verification-url" content="{{ route('job.verification') }}"></head><body><div class="shell"><aside class="sidebar"><div class="brand">Fixifier<span>+</span></div><p class="sub">ADMIN OPERATIONS</p><nav class="sidenav" id="nav"></nav><a href="{{ route('job.verification') }}" style="display:block;margin:12px 0;padding:12px 14px;border-radius:10px;color:inherit;text-decoration:none;font-weight:650">Job Verification</a><p class="mini" style="margin:28px 12px;color:#a9b9d7">Manage your marketplace records.</p></aside><main class="main"><header class="top"><div><h1 id="title">Operations Overview</h1><div class="muted">Manage trust, jobs, disputes and marketplace activity</div></div><div class="topright"><span class="badge">Administrator</span><button class="btn secondary" onclick="load()">Refresh</button><button class="btn ghost" onclick="logout()">Sign out</button></div></header><section id="overview" class="section active"></section><section id="technicians" class="section"></section><section id="bookings" class="section"></section><section id="evidence" class="section"></section><section id="disputes" class="section"></section><section id="customers" class="section"></section><section id="finance" class="section"></section><section id="audit" class="section"></section></main></div><div class="modalback" id="modalback" onclick="if(event.target===this)closeModal()"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="row"><h2 id="modalTitle"></h2><button class="btn ghost" onclick="closeModal()">✕ Close</button></div><div id="modalContent"></div></div></div><div class="toast" id="toast" role="status"></div><script src="{{ asset('js/admin.js') }}" defer></script></body></html>
